begin;
select no_plan();
create extension if not exists dblink with schema extensions;

create temporary table moderation_race_fixture(connection_string text,waiting_pid integer);
insert into moderation_race_fixture values(format('hostaddr=%s port=%s dbname=%L user=%L password=postgres options=%L',coalesce(host(inet_server_addr()),'127.0.0.1'),inet_server_port(),current_database(),current_user,'-c statement_timeout=12000 -c lock_timeout=8000'),null);
create function pg_temp.wait_for_lock(p_pid integer,p_timeout interval default interval '5 seconds') returns boolean language plpgsql as $$declare deadline timestamptz:=clock_timestamp()+p_timeout; begin loop if exists(select 1 from pg_stat_activity where pid=p_pid and wait_event_type='Lock') then return true; end if; if clock_timestamp()>=deadline then return false; end if; perform pg_sleep(.01); end loop; end$$;

select extensions.dblink_connect('m7_setup',connection_string),extensions.dblink_connect('m7_one',connection_string),extensions.dblink_connect('m7_two',connection_string) from moderation_race_fixture;
select extensions.dblink_exec('m7_setup',$cleanup$
 set session_replication_role=replica;
 delete from public.rate_limit_events where user_id::text like 'b9800000-0000-4000-8000-%';
 delete from public.benefit_claim_moderation_requests where claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_claim_reaction_requests where claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_claim_official_reviews where claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_claim_merges where source_claim_id::text like 'b9810000-0000-4000-8000-%' or target_claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_claim_events where claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_claim_reactions where claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_claims where claim_id::text like 'b9810000-0000-4000-8000-%';
 delete from public.benefit_publications where company_id='KR-BIZ-9998000001';
 delete from public.benefit_companies where company_id='KR-BIZ-9998000001';
 delete from public.user_roles where user_id::text like 'b9800000-0000-4000-8000-%';
 delete from auth.identities where user_id::text like 'b9800000-0000-4000-8000-%';
 delete from public.profiles where id::text like 'b9800000-0000-4000-8000-%';
 delete from auth.users where id::text like 'b9800000-0000-4000-8000-%';
 update private.benefit_feature_settings set enabled=false,updated_at=clock_timestamp() where setting_key in ('claims_write_enabled','claim_reactions_write_enabled');
 set session_replication_role=origin
$cleanup$);
select extensions.dblink_exec('m7_setup',$setup$
 insert into auth.users(id,aud,role,email) select ('b9800000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,'authenticated','authenticated','m7-'||g||'@race.test' from generate_series(1,5) g;
 insert into public.profiles(id,github_user_id,login) select ('b9800000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,99980000+g,'m7-'||g from generate_series(1,5) g;
 insert into public.user_roles(user_id,role) select id,case when id='b9800000-0000-4000-8000-000000000001' then 'admin' else 'member' end from public.profiles where id::text like 'b9800000-0000-4000-8000-%';
 insert into auth.identities(provider_id,user_id,identity_data,provider) select login,id,'{}','google' from public.profiles where id::text like 'b9800000-0000-4000-8000-%';
 insert into public.benefit_companies(company_id,identity_class,display_name,normalized_name,is_searchable,source_edition) values('KR-BIZ-9998000001','registered_business','Task 7 Race Company','task 7 race company',true,'race-test');
 update private.benefit_feature_settings set enabled=true,updated_at=clock_timestamp() where setting_key in ('claims_write_enabled','claim_reactions_write_enabled');
 insert into public.benefit_claims(claim_id,company_id,submitter_id,client_key,payload_fingerprint,category_id,title,normalized_title,description,normalized_eligibility,observed_on) select ('b9810000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,'KR-BIZ-9998000001','b9800000-0000-4000-8000-000000000005',gen_random_uuid(),repeat(g::text,64),'health','Race claim '||g,'race claim '||g,'Race fixture','',date '2026-01-01' from generate_series(1,8) g;
$setup$);
select extensions.dblink_exec(c,$helpers$
 create or replace function pg_temp.try_react(c uuid,r text,k uuid) returns text language plpgsql as $$begin return public.set_benefit_claim_reaction_v1(c,r,k)::text; exception when others then return 'ERR:'||sqlstate; end$$;
 create or replace function pg_temp.try_moderate(k uuid,c uuid,rev bigint,st text,a text,t uuid default null) returns text language plpgsql as $$begin return public.moderate_benefit_claim_v1(k,c,rev,st,a,t,'race evidence','official_website',date '2026-01-01','https://example.com/race')::text; exception when others then return 'ERR:'||sqlstate; end$$;
 create or replace function pg_temp.try_verify(c uuid,st text,rev bigint,k uuid) returns text language plpgsql as $$begin return public.officially_verify_benefit_claim_v1(c,st,rev,'Race official','Race official description',null,null,'official_website','https://example.com/race',date '2026-01-01','race note',k)::text; exception when others then return 'ERR:'||sqlstate; end$$;
 grant execute on function pg_temp.try_react(uuid,text,uuid),pg_temp.try_moderate(uuid,uuid,bigint,text,text,uuid),pg_temp.try_verify(uuid,text,bigint,uuid) to authenticated
$helpers$) from unnest(array['m7_one','m7_two']) c;
create temporary table worker_results(race text,worker integer,result text);

-- hide commits while a reaction waits and rechecks visibility.
select extensions.dblink_exec('m7_one','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001''');
insert into worker_results select 'hide-reaction',1,result from extensions.dblink('m7_one',$q$select pg_temp.try_moderate('b9820000-0000-4000-8000-000000000001','b9810000-0000-4000-8000-000000000001',1,'submitted','hide')$q$) r(result text);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000002''');
update moderation_race_fixture set waiting_pid=(select pid from extensions.dblink('m7_two','select pg_backend_pid()') r(pid int));
select extensions.dblink_send_query('m7_two',$q$select pg_temp.try_react('b9810000-0000-4000-8000-000000000001','confirm','b9820000-0000-4000-8000-000000000002')$q$);
select ok((select pg_temp.wait_for_lock(waiting_pid) from moderation_race_fixture),'hide/reaction worker deterministically waits on claim');
select extensions.dblink_exec('m7_one','commit'); insert into worker_results select 'hide-reaction',2,result from extensions.dblink_get_result('m7_two') r(result text); select count(*) from extensions.dblink_get_result('m7_two') r(result text); select extensions.dblink_exec('m7_two','commit');
select is((select string_agg(result,',' order by worker) from worker_results where race='hide-reaction' and result like 'ERR:%'),'ERR:22023','hide wins and queued reaction fails visibly');

-- official verification commits before dispute; dispute remains real but authority stays active.
select extensions.dblink_exec('m7_one','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001''');
insert into worker_results select 'verify-dispute',1,result from extensions.dblink('m7_one',$q$select pg_temp.try_verify('b9810000-0000-4000-8000-000000000002','submitted',1,'b9820000-0000-4000-8000-000000000003')$q$) r(result text);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000002''');
update moderation_race_fixture set waiting_pid=(select pid from extensions.dblink('m7_two','select pg_backend_pid()') r(pid int)); select extensions.dblink_send_query('m7_two',$q$select pg_temp.try_react('b9810000-0000-4000-8000-000000000002','dispute','b9820000-0000-4000-8000-000000000004')$q$);
select ok((select pg_temp.wait_for_lock(waiting_pid) from moderation_race_fixture),'verify/dispute serializes on claim'); select extensions.dblink_exec('m7_one','commit'); insert into worker_results select 'verify-dispute',2,result from extensions.dblink_get_result('m7_two') r(result text); select count(*) from extensions.dblink_get_result('m7_two') r(result text); select extensions.dblink_exec('m7_two','commit');
select is((select state from extensions.dblink((select connection_string from moderation_race_fixture),$$select c.status||':'||p.status||':'||p.trust_tier||':'||(select count(*) from public.benefit_publications x where x.provenance->>'claim_id'=c.claim_id::text and x.source_type='claim_reaction') from public.benefit_claims c join public.benefit_publications p on p.publication_id=c.official_publication_id where c.claim_id='b9810000-0000-4000-8000-000000000002'$$) r(state text)),'disputed:active:official_verified:0','verify/dispute keeps official authority, disputed claim, and no community publication');

-- a reaction that commits before merge is transferred, never ghosted.
select extensions.dblink_exec('m7_one','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000002'''); insert into worker_results select 'merge-reaction',1,result from extensions.dblink('m7_one',$q$select pg_temp.try_react('b9810000-0000-4000-8000-000000000003','dispute','b9820000-0000-4000-8000-000000000005')$q$) r(result text);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); update moderation_race_fixture set waiting_pid=(select pid from extensions.dblink('m7_two','select pg_backend_pid()') r(pid int)); select extensions.dblink_send_query('m7_two',$q$select pg_temp.try_moderate('b9820000-0000-4000-8000-000000000006','b9810000-0000-4000-8000-000000000003',2,'disputed','merge','b9810000-0000-4000-8000-000000000004')$q$);
select ok((select pg_temp.wait_for_lock(waiting_pid) from moderation_race_fixture),'merge waits behind source reaction'); select extensions.dblink_exec('m7_one','commit'); insert into worker_results select 'merge-reaction',2,result from extensions.dblink_get_result('m7_two') r(result text); select count(*) from extensions.dblink_get_result('m7_two') r(result text); select extensions.dblink_exec('m7_two','commit');
select is((select state from extensions.dblink((select connection_string from moderation_race_fixture),$$select s.status||':'||s.merged_into_claim_id||':'||(select count(*) from public.benefit_claim_reactions where claim_id=s.claim_id)||':'||(select count(*) from public.benefit_claim_reactions where claim_id=s.merged_into_claim_id and reaction='dispute') from public.benefit_claims s where s.claim_id='b9810000-0000-4000-8000-000000000003'$$) r(state text)),'merged:b9810000-0000-4000-8000-000000000004:0:1','merge transfers reaction and leaves terminal source without ghosts');

-- establish official claim, then race reverify against explicit withdrawal.
select result from extensions.dblink('m7_setup',$q$select set_config('request.jwt.claim.sub','b9800000-0000-4000-8000-000000000001',false); set local role authenticated; select public.officially_verify_benefit_claim_v1('b9810000-0000-4000-8000-000000000005','submitted',1,'Initial','Initial official',null,null,'official_website','https://example.com/initial',date '2026-01-01','initial note','b9820000-0000-4000-8000-000000000007')::text$q$) r(result text);
select extensions.dblink_exec('m7_one','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); insert into worker_results select 'reverify-withdraw',1,result from extensions.dblink('m7_one',$q$select pg_temp.try_verify('b9810000-0000-4000-8000-000000000005','submitted',2,'b9820000-0000-4000-8000-000000000008')$q$) r(result text);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); update moderation_race_fixture set waiting_pid=(select pid from extensions.dblink('m7_two','select pg_backend_pid()') r(pid int)); select extensions.dblink_send_query('m7_two',$q$select pg_temp.try_moderate('b9820000-0000-4000-8000-000000000009','b9810000-0000-4000-8000-000000000005',2,'submitted','withdraw_official')$q$);
select ok((select pg_temp.wait_for_lock(waiting_pid) from moderation_race_fixture),'reverify/withdraw serializes on claim'); select extensions.dblink_exec('m7_one','commit'); insert into worker_results select 'reverify-withdraw',2,result from extensions.dblink_get_result('m7_two') r(result text); select count(*) from extensions.dblink_get_result('m7_two') r(result text); select extensions.dblink_exec('m7_two','commit');
select is((select result from worker_results where race='reverify-withdraw' and worker=2),'ERR:40001','stale official withdrawal loses by CAS');
select is((select state from extensions.dblink((select connection_string from moderation_race_fixture),$$select count(*)||':'||count(*) filter(where status='active')||':'||(select count(*) from public.benefit_claim_official_reviews where claim_id='b9810000-0000-4000-8000-000000000005' and action in ('verify','reverify')) from public.benefit_publications where provenance->>'claim_id'='b9810000-0000-4000-8000-000000000005' and source_type='claim_official'$$) r(state text)),'2:1:2','official race leaves one serial two-publication lineage and two evidence reviews');

-- same actor/key, conflicting moderation and official intent: one effect only.
select extensions.dblink_exec('m7_one','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); insert into worker_results select 'key-conflict',1,result from extensions.dblink('m7_one',$q$select pg_temp.try_moderate('b9820000-0000-4000-8000-000000000010','b9810000-0000-4000-8000-000000000006',1,'submitted','hide')$q$) r(result text);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); update moderation_race_fixture set waiting_pid=(select pid from extensions.dblink('m7_two','select pg_backend_pid()') r(pid int)); select extensions.dblink_send_query('m7_two',$q$select pg_temp.try_verify('b9810000-0000-4000-8000-000000000006','submitted',1,'b9820000-0000-4000-8000-000000000010')$q$);
select ok((select pg_temp.wait_for_lock(waiting_pid) from moderation_race_fixture),'same client key conflict waits on intent lock'); select extensions.dblink_exec('m7_one','commit'); insert into worker_results select 'key-conflict',2,result from extensions.dblink_get_result('m7_two') r(result text); select count(*) from extensions.dblink_get_result('m7_two') r(result text); select extensions.dblink_exec('m7_two','commit');
select is((select result from worker_results where race='key-conflict' and worker=2),'ERR:22023','conflicting same-key official intent is rejected');
select is((select state from extensions.dblink((select connection_string from moderation_race_fixture),$$select c.status||':'||(select count(*) from public.benefit_claim_moderation_requests where claim_id=c.claim_id)||':'||(select count(*) from public.benefit_claim_events where claim_id=c.claim_id)||':'||(select count(*) from public.benefit_publications where provenance->>'claim_id'=c.claim_id::text) from public.benefit_claims c where c.claim_id='b9810000-0000-4000-8000-000000000006'$$) r(state text)),'hidden:1:1:0','same-key conflict has exactly one request/event and no official effect');

-- injected late publication and event failures are caught, committed, and leave zero effects.
select extensions.dblink_exec('m7_setup',$q$create function public.m7_reject() returns trigger language plpgsql as $$begin raise exception 'injected late failure'; end$$; create trigger m7_publication_failure before insert on public.benefit_publications for each row when(new.source_type='claim_official') execute function public.m7_reject()$q$);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); insert into worker_results select 'late-publication',1,result from extensions.dblink('m7_two',$q$select pg_temp.try_verify('b9810000-0000-4000-8000-000000000007','submitted',1,'b9820000-0000-4000-8000-000000000011')$q$) r(result text); select extensions.dblink_exec('m7_two','commit');
select extensions.dblink_exec('m7_setup','drop trigger m7_publication_failure on public.benefit_publications; drop function public.m7_reject()');
select is((select result from worker_results where race='late-publication'),'ERR:P0001','late publication failure is collected');
select is((select state from extensions.dblink((select connection_string from moderation_race_fixture),$$select revision||':'||(select count(*) from public.benefit_claim_moderation_requests where claim_id=c.claim_id)||':'||(select count(*) from public.benefit_claim_official_reviews where claim_id=c.claim_id)||':'||(select count(*) from public.benefit_publications where provenance->>'claim_id'=c.claim_id::text) from public.benefit_claims c where claim_id='b9810000-0000-4000-8000-000000000007'$$) r(state text)),'1:0:0:0','late publication failure rolls back claim/request/review/publication');
select extensions.dblink_exec('m7_setup',$q$create function public.m7_reject_event() returns trigger language plpgsql as $$begin raise exception 'injected late event failure'; end$$; create trigger m7_event_failure before insert on public.benefit_claim_events for each row when(new.claim_id='b9810000-0000-4000-8000-000000000008') execute function public.m7_reject_event()$q$);
select extensions.dblink_exec('m7_two','begin; set local role authenticated; set local request.jwt.claim.sub=''b9800000-0000-4000-8000-000000000001'''); insert into worker_results select 'late-event',1,result from extensions.dblink('m7_two',$q$select pg_temp.try_moderate('b9820000-0000-4000-8000-000000000012','b9810000-0000-4000-8000-000000000008',1,'submitted','hide')$q$) r(result text); select extensions.dblink_exec('m7_two','commit');
select extensions.dblink_exec('m7_setup','drop trigger m7_event_failure on public.benefit_claim_events; drop function public.m7_reject_event()');
select is((select result from worker_results where race='late-event'),'ERR:P0001','late event failure is collected');
select is((select state from extensions.dblink((select connection_string from moderation_race_fixture),$$select status||':'||revision||':'||(select count(*) from public.benefit_claim_moderation_requests where claim_id=c.claim_id)||':'||(select count(*) from public.benefit_claim_events where claim_id=c.claim_id) from public.benefit_claims c where claim_id='b9810000-0000-4000-8000-000000000008'$$) r(state text)),'submitted:1:0:0','late event failure rolls back all moderation state');

select ok((select count(*)=12 and bool_and(result is not null) from worker_results),'every dispatched worker result or error was collected');
select extensions.dblink_exec('m7_setup',$cleanup$
 set session_replication_role=replica;
 delete from public.rate_limit_events where user_id::text like 'b9800000-0000-4000-8000-%'; delete from public.benefit_claim_moderation_requests where claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_claim_reaction_requests where claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_claim_official_reviews where claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_claim_merges where source_claim_id::text like 'b9810000-0000-4000-8000-%' or target_claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_claim_events where claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_claim_reactions where claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_claims where claim_id::text like 'b9810000-0000-4000-8000-%'; delete from public.benefit_publications where company_id='KR-BIZ-9998000001'; delete from public.benefit_companies where company_id='KR-BIZ-9998000001'; delete from public.user_roles where user_id::text like 'b9800000-0000-4000-8000-%'; delete from auth.identities where user_id::text like 'b9800000-0000-4000-8000-%'; delete from public.profiles where id::text like 'b9800000-0000-4000-8000-%'; delete from auth.users where id::text like 'b9800000-0000-4000-8000-%'; update private.benefit_feature_settings set enabled=false,updated_at=clock_timestamp() where setting_key in ('claims_write_enabled','claim_reactions_write_enabled');
 set session_replication_role=origin
$cleanup$);
select is((select n from extensions.dblink((select connection_string from moderation_race_fixture),$$select count(*)::int from public.benefit_companies where company_id='KR-BIZ-9998000001'$$) r(n int)),0,'all concurrency fixtures are removed');
select extensions.dblink_disconnect('m7_one'); select extensions.dblink_disconnect('m7_two'); select extensions.dblink_disconnect('m7_setup');
select * from finish();
rollback;
